/** TargetOption */
export interface TargetOptions {
  [key: string]: TargetOption;
}

/** TargetOption */
export interface TargetOption {
  /** Export function */
  getExportData?: (accountingData: AccountingData, schemeId?: string, target?: TargetOption) => any[];

  /** List of supported schemes */
  schemes?: { id: string, label: string }[],

  /** Default export method */
  defaultExportMethod?: string;
  /** Boolean indicating if the csv export should contain quoted strings */
  noCsvQuotedStrings?: boolean;

  /** Boolean indicating if the csv export should contain byte order mark */
  noCsvBom?: boolean;

  /** Format data as text*/
  formatAsText?: (data: any[], isFinnish: boolean) => string;

  /** File extension for the text files. If not given, the default extension will be used */
  textFileExtension?: string;

  /** List of dimensions from the settings. */
  dimensions?: string[];
}

