  private static formatAsDigiaText(data: any[], _isFinnish: boolean): string {
    const textRows: any[] = [];
    data = data.slice(1);
    for (const row of data) {
      row[0] = this.padRight(row[0] ? Dates.format(row[0], "DDMMYY") : "",6);
      row[1] = this.padRight(row[1],4);
      row[2] = this.padLeft(row[2],8);
      row[3] = this.padRight(row[3],8);
      row[4] = this.padLeft(row[4],1);
      row[5] = this.padLeft(Numeric.toString(Numeric.round((row[5] ?? 0) * 100, 0) as number), 11, "0");
      row[6] = this.padRight(row[6],3);
      row[7] = this.padLeft(Numeric.toString(Numeric.round((row[7] ?? 0) * 1000000000, 0) as number), 17, "0");
      row[8] = this.padRight(row[8],30);
      row[9] = this.padRight(null,6);
      row[10] = this.padRight(row[10],3);
      row[11] = this.padRight(row[11],8);
      row[12] = this.padRight(row[12],8);
      row[13] = this.padRight(row[13],8);
      row[14] = this.padRight(row[14],8);
      row[15] = this.padRight(row[15],8);
      row[16] = this.padRight(row[16],8);
      row[17] = this.padRight(row[17],8);
      row[18] = this.padRight(row[18],8);
      row[19] = this.padRight(row[19],8);

      textRows.push(row.join(""));
    }
    if (textRows.length > 0) {
      // This is required by Digia: every row must end to CRLF even the last.
      textRows.push("");
    }
    return textRows.join("\r\n");
  }
