  private static getIScalaExportData(data: AccountingData, target: TargetOption): any[] {

    const result: any[] = [];
    const header: any[] = ["TransNum", "TransDate","Flag","Amnt","TransTxt","Code1","Code2","TransLineType","UserEntryBy","Account"];

    const dimensionHeaders = (target.dimensions ?? []).filter((x) => !((x[0] ?? "_").startsWith("_"))).map((x) => x.toLowerCase());

    header.push(...dimensionHeaders.map((x, i) => "AccDim" +(i+1)));

    result.push(header);

    const entryDate = this.getEntryDate(data) || Dates.getToday();

    for (const rowData of data?.ledgerAccounts ?? []) {
      const keyEntriesRows: {
        /** Entries */
        entries: LedgerEntry[],
        /** Dimensions */
        dimensions: any[],
        /** DimensionsId */
        dimensionsId: string
      }[] = [];
      for (const entryData of rowData?.entries ?? []) {
        const rowDataEntriesDimensions: string[] = [];
        for (const dimensionHeader of dimensionHeaders) {
            rowDataEntriesDimensions.push(entryData.dimension?.dimensions ? (entryData.dimension.dimensions[dimensionHeader] || "") : "");
        }
        let keyEntryRows: {
          /** Entries */
          entries: LedgerEntry[],
          /** Dimensions */
          dimensions: any[],
          /** DimensionsId */
          dimensionsId: string
        } | undefined = keyEntriesRows.find((x) => x.dimensionsId === rowDataEntriesDimensions.join("-"));
        if (keyEntryRows == null) {
          keyEntryRows = { entries: [], dimensions: rowDataEntriesDimensions, dimensionsId: rowDataEntriesDimensions.join("-") };
          keyEntriesRows.push(keyEntryRows);
        }
        keyEntryRows.entries.push(entryData);
      }
      // Append results
      for (const keyEntryRows of keyEntriesRows) {
        const row: any[] = [];
        // TransNum
        row.push(null);
        // TransDate
        row.push(Dates.asJSDate(entryDate));
        // Flag
        row.push("0");
        // Amnt
        const saldo = Numeric.round(keyEntryRows.entries.reduce((sum, x) => sum + (x.isDebit ? (x.amount ?? 0) : -1.0 * (x.amount ?? 0)), 0));
        row.push(saldo);
        //TransTxt
        row.push(rowData.accountName);
        //Code1
        row.push(null);
        //Code2
        row.push(null);
        //TransLineType
        row.push("A");
        //UserEntryBy
        row.push("SCSNepto");
        //Account
        row.push(rowData.accountNumber);
        // AccDimX
        for (let i = 0; i < dimensionHeaders.length; i++) {
          row.push(keyEntryRows.dimensions[i]);
        }
        result.push(row);
      }
    }
    return result;
  }

